from heapq import heappop, heappush

def solve(n, t, a, b, c):
    if 2 * (n - 2) > t:
        return "Impossible"

    # Create a max-heap with sensor positions
    sensors = []
    for i in range(n - c + 1):
        for j in range(n - c + 1):
            heappush(sensors, (-abs(i + j - (a + (c - 1) * i)), i, j))

    # Escape steps
    steps = ['R'] * (n - 1) + ['U'] * (n - 1)

    while steps and steps[-1] != 'R' and steps[0] != 'U':
        current = heappop(sensors)
        char = steps.pop()

        if steps and steps[-1] == 'R' or steps[-1] == 'U':
            steps.append('U')
            continue

        if current[0] + current[0] > t:
            continue

        if char == 'R':
            heappush(sensors, (current[1], current[0] + 1, current[1] + (c - 1)))
        elif char == 'U':
            heappush(sensors, ((current[0] + 1) - (c - 1) * current[1], current[0] + 1, current[1]))

    return ''.join(steps)

