            factor = 1
    return value % MOD

def is_valid_expression(expression, index):
    if expression[index] == "(":
        return False
    if index == len(expression) - 1:
        return True
    if expression[index] == "+":
        left = calculate_value(expression, index)
        right = calculate_value(expression, index + 1)
        return left * right % MOD == 0
    return True

def evaluate(index, expression):
    if not is_valid_expression(expression, index):
        return -1
    left = calculate_value(expression, index)
    if index == len(expression) - 1:
        return left
    right = 0
    if expression[index + 1] == "+":
        right = calculate_value(expression, index)
    else:
