```python
from collections import defaultdict, deque
from typing import List

class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x: int) -> int:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x: int, y: int):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            if self.rank[root_x] > self.rank[root_y]:
                self.parent[root_y] = root_x
            elif self.rank[root_x] < self.rank[root_y]:
                self.parent[root_x] = root_y
            else:
                self.parent[root_y] = root_x
                self.rank[root_x] += 1

class ChessBoard:
    def __init__(self, n: int, m: int):
        self.rym = [[-1] * m for _ in range(2 * n)]  # Store all available cells
        self.univ = UnionFind(2 * n * m)

    def add_unavailable_cell(self, r: int, c: int):
        x = c + r // 2
        if x < n and x % 2 == r % 2 and x < 2 * n:
            self.rym[x][c] = 0

    def expand_available_cell(self, r: int, c: int) -> None:
        x = c + r // 2
        if x < n and x % 2 == r % 2 and x < 2 * n:
            if self.rym[x][c] == -1:
                return
            self.rym[x][c] = 0

    def solve(self, q: int, queries: List[List[int]]) -> None:
        n, m, q = 2, 2, q
        reject = deque()
        board_state = defaultdict(int)

        for i in range(q):
            r, c = queries[i][0], queries[i][1]
            if self.rym[r - 1][c - 1] == -1:  # Check if query is a hack
                r, c = queries[0][0], queries[0][1]
                r -= 1  # Adjust r for 0-based indexing
                c -= 1  # Adjust c for 0-based indexing
            else:
                self.expand_available_cell(r, c)
                self.univ.union(r * m + c, r * m + c - 1)
                board_state[(r, c)] = 1

            all_zero_state = True
            for x, b in self.rym:
                if sum(x) != 0:
                    all_zero_state = False
            if not all_zero_state:
                reject.append(i)

            if reject:
                if i in reject:
                    board_state[i] = 0
            else:
                board_state[i] = 1

        for k, v in board_state.items():
            r, c = k
            rows = r // 2
            cols = r % 2
            row = r

            if v == 0:
                continue

            while row > 0 and cols == 0:
                if board_state[(rows - 1, cols)] == 1 and self.rym[row - 1][cols] == 1:
                    break

                if self.rym[row][cols] == -1:
                    return 'NO'
                self.rym[row][cols] = 0

            while row < n - 1 and cols == 1:
                if board_state[(rows + 1, cols)] == 1 and self.rym[row + 1][cols] == 1:
                    break

                if self.rym[row][cols] == -1:
                    return 'NO'
                self.rym[row][cols] = 0

            while row < n - 1 and cols == 1:
                if self.rym[row][cols] == -1:
                    return 'NO'
                self.rym[row][cols] = 0

            while row > 0 and cols == 1:
                if board_state[(rows + 1, cols - 1)] == 1 and self.rym[row + 1][cols - 1] == 1:
                    break

                if self.rym[row][cols - 1] == -1:
                    return 'NO'
                self.rym[row][cols - 1] = 0

            while row < n - 1 and cols == 0:
                if board_state[(rows - 1, cols)] == 1 and self.rym[row - 1][cols] == 1:
                    break

                if self.rym[row][cols] == -1:
                    return 'NO'
                self.rym[row][cols] = 0

        return 'YES'


