class ApplicationOptimizer:
    def optimize_parameters(self, n, w, user_data):
        app_cost = [0] * (w + 1)  # Initialize with 0 cost for free version
        best_cost = [float('-inf')] * (w + 1)  # To track the best cost for each c

        for ai, bi in user_data:
            if bi == 0 and ai > app_cost[0]:
                app_cost[0] = ai

            if bi > app_cost[0]:
                app_cost[0] = min(app_cost[0], bi)
            else:
                app_cost[bi] = (bi * w + app_cost[bi - 1]) if bi < len(app_cost) else bi * w

            pos = bisect.bisect(best_cost, app_cost[bi])
            bisect.insort(best_cost, app_cost[bi])

            if bi == n:
                continue

            for next_c in range(min(bi, w), 0, -1):
                while app_cost[next_c] > bi * w + app_cost[next_c - 1] and best_cost[app_cost[next_c]] < app_cost[next_c] + w + 1:
                    app_cost[next_c] = bi * w + app_cost[next_c - 1]
                    next_c -= 1
                if best_cost[next_c] < app_cost[next_c]:
                    best_cost[next_c] = app_cost[next_c]

        # Parting the magic
        optimal_p = [float('inf')] * (w + 1)
        for i in range(w, 1, -1):
            if best_cost[i] > app_cost[i]:
                optimal_p[i] = app_cost[i] + 1

        return optimal_p

