MOD = 998244353
INF = 1e15

def mod_pow(x, p):
    ret = 1
    while p:
        if p & 1:
            ret = ret * x % MOD
        x = x * x % MOD
        p >>= 1
    return ret

class Chk5001:
    def __init__(self):
        self.streets = {i: mod_pow(i, 5001) for i in range(1, INF+1)}
        self.streets[0] = 0

    def f(self, x, y=0):
        if x == INF:
            return y
        return self.f(self.streets[x], y + self.streets[x] * (x for x in range(y+1, x))[x > 0])

    def dfs(self, x):
        if 2*x < INF and x > 0:
            y = self.dfs(x * 2)
            x = self.dfs(x / 2)
            return y * self.f(x)
        return (x + 1 if x < INF else INF) >> 1

