from typing import List

def can_place_kings(board: List[List[bool]], x: int, y: int, free_cells: List[List[int]]) -> bool:
    n, m = len(board), len(board[0])
    possible_placements = set()

    def dfs(x: int, y: int, count: int, off_x: int, off_y: int) -> bool:
        if count == x * y:
            possible_placements.add((x, y))
            return True

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx * off_x, y + dy * off_y
            if 0 <= nx < n and 0 <= ny < m and not board[nx][ny]:
                board[nx][ny] = True
                if dfs(nx, ny, count + 1, off_x, off_y):
                    return True
                board[nx][ny] = False
        return False

    for off_x, off_y in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
        dfs(x, y, 1, off_x, off_y)

    return len(possible_placements) == 0 or free_cells[0] == (x, y)


def main(board: List[List[bool]], n_queries: List[List[int]]) -> None:
    for x, y in n_queries:
        if board[x-1][y-1]:
            board[x-1][y-1] = False
        else:
            board[x-1][y-1] = True
        if not can_place_kings(board, x, y, n_queries[:]):
            print("NO")
            return

    print("YES")


