import heapq
from collections import defaultdict, deque

def dijkstra_shortest_path(graph, start, end):
    n = len(graph)
    dist = {node: float('inf') for node in range(n + 1)}
    dist[start] = 0
    pq = [(0, start)]  # Priority queue of (cost, node)

    while pq:
        cost, node = heapq.heappop(pq)

        if node == end:
            break

        for neighbor, weight in graph[node].items():
            new_cost = cost + weight
            if new_cost < dist[neighbor]:
                dist[neighbor] = new_cost
                heapq.heappush(pq, (new_cost, neighbor))

    return dist[end]

def minimum_capacity_needed(n, central_nodes, graph, mission_guards, missions):
    graph = defaultdict(dict)

    for u, v, weight in missions:
        graph[u][v] = [weight]
        graph[v][u] = [weight]

    capacities = [1] * n  # Initial battery capacity for each node

    for mission in missions:
        u, v = mission
        if u not in central_nodes or v not in central_nodes:
            capacities[u] = min(capacities[u], capacities[v])
            capacities[v] = min(capacities[u], capacities[v])

    for i in range(n - 1, -1, -1):
        capacities[i] = min(capacities[i], capacities[i + 1]) + 1

    results = []
    for mission in missions:
        u, v = mission
        if u == v:
            results.append(capacities[u])
        else:
            capacities_u = 0
            if u in central_nodes:
                capacities_u = min(capacities[u], capacities[v])
            capacities_v = 0
            if v in central_nodes:
                capacities_v = min(capacities[u], capacities[v])

            capacities_u = min(capacities_u, capacities_v)

            if capacities_u == capacities[v]:
                capacities_v = capacities[u]

            capacity = dijkstra_shortest_path(graph, capacities_u, u)

            results.append(min(capacity, capacities_v))

    return results

