def max_interval_value(n: int, k: int, intervals: List[List[int]]) -> int:
    import math

    def calculate_possible_values() -> int:
        subsets = [[] for _ in range(1 << k)]
        for i in range(n):
            for j in range(i, n):
                subsets[int(i & j)].append(i + 1)

        unique_subsets = set(subsets)
        total_values = 0

        for unique_subset in unique_subsets:
            values = [set() for _ in range(len(unique_subset))]

            for i in range(n):
                intersection = set()
                for j in unique_subset:
                    if i >= j:
                        intersection |= subsets[j]
                    else:
                        intersection -= set([subsets[j_][i] for j_ in unique_subset[::-1] if j_ > j])

                if len(intersection) == len(subsets[j]):
                    values[i - unique_subset[0]].add(subsets[j][i])

            total_values += sum(len(set(v)) for v in values if v)

        return total_values

    for i in range(k):
        if k - i == len(intervals):
            return calculate_possible_values()
