def power(b, k, p):
    """Recursive function to compute b^k % p"""
    if k == 0:
        return 1
    half = power(b, k // 2, p)
    res = (half**2) % p
    if k % 2 == 0:
        return res
    else:
        return (res * b) % p

def inverse(a, p):
    """Recursive function to compute a^(-1) % p"""
    if a == 1:
        return 1
    else:
        return (p - 1) * inverse(a, p) + inverse(a * a, p) * p
