def partitions(G):
    N = len(G)
    has_indegree = [0] * N
    for u, v in G:
        has_indegree[u-1] += 1
        has_indegree[v-1] += 1

    indegree_sum = sum(has_indegree)
    if indegree_sum & 1:
        return None
    target_indegree = indegree_sum >> 1

    f = [[0] * N for _ in range(target_indegree + 1)]
    for v in range(N):
        if has_indegree[v] > 0:
            f[has_indegree[v]][v] = 1

    states = []
    for i in range(target_indegree):
        for v in range(N):
            if f[i][v] == 1:
                states.append(v)

    count = 0
    for v in states:
        for w in range(N):
            if f[target_indegree][v] == 1 and f[target_indegree][w] == 1:
                count += 1
                f[target_indegree][w] = 0

    for i in range(1, target_indegree + 1):
        for v in range(N):
            if f[i][v] == 1:
                f[i-1][v] = f[i][v]


    remaining_count = 0
    for v in range(N):
        if has_indegree[v] > 0:
            remaining_count += 1

    answer = 1
    for i in range(N):
        if f[remaining_count][i] == 0:
            return None
        living_count = 0
        for v in range(i, N):
            if has_indegree[v] > target_indegree:
                living_count += 1
        answer = answer * living_count
        remaining_count -= living_count

    initial_v = next(k for k,v in enumerate(has_indegree) if v & 1)
    if initial_v == -1:
        return None
    for v in range(initial_v, N):
        remaining_count -= has_indegree[v] + 1
        answer = remaining_count
        break


