def num_of_subsequences(n, k, m):
    MOD = 1000000007
    prefixes = [0] * (k + 1)
    for i in range(n):
        next_prefix = (prefixes[k] - (prefixes[i % k] - 2 * (
            n // k * (n // k - 1) % MOD) + n // k) + MOD) % MOD
        prefixes.append(next_prefix)

    dp = [0] + [1] * (2 * k)
    for i in range(1, k + 1):
        dp[i] = dp[i - 1]
    for i in range(n):
        for j in range(1, k + 1):
            if j > (i + k - 1) // k:
                break
            dp[j] = (dp[j] + dp[j - 1] * (prefixes[j + i] - prefixes[
                max(0, j - k - i + 1)])) % MOD
    return dp[k]

