from collections import defaultdict
from heapq import heappop, heappush

def dijkstra(graph, start, end, k):
    distances = {node: float('inf') for node in range(1, k+1)}
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_dist, current_node = heappop(priority_queue)

        if current_node == end:
            return current_dist

        if current_dist > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_dist + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(priority_queue, (distance, neighbor))

    return float('inf')  # Represents that there is no path between given start and end node

