    if a == n and b == 1 and c == 1:
        return 'UUURUURURURURURURURURURURURURURU'

    n -= 2
    if c == 1:
        path = 'RRRUURURUURURURURURURURURURURUR'
        count = min(2 * n - 1, t + abs(a - 1) + abs(b - 2) + 4) - 1
        steps = deque(path[:count - 1], maxlen=2 * n)
        steps.rotate(-2)
        steps.extend('U' * (3 * n - 1) + 'R' * (3 * n - 1))
        return ''.join(steps)
    elif c == n:
        path = 'UUURUURURURURURURURURURURURUR'
        count = min(2 * n - 1, t + abs(a - 2) + abs(b - 1) + 4) - 1
        steps = deque(path[:count - 1], maxlen=2 * n)
        steps.rotate(-2)
        steps.extend('R' * (3 * n - 1) + 'U' * (3 * n - 1))
        return ''.join(steps)
    else:
        steps = deque('URUR' * n, maxlen=4 * n - 2)
        c1 = min(2 * n - 1, t + abs(a - 1) + abs(b - 2) + 2 * abs(c - 1) + 1) - 1
        steps.rotate(c1)
        count = 3 * n - 1
        for i in range(c + 1):
            for j in range(c + 1):
                steps[-count] = 'U' if i > 0 and j == 0 else 'R' if i == j and (i >= c * 2 or j >= 4 - i and n - j > i - c) else 'U' if i == j and (i >= c * 2 or j >= i - c) else 'R'
                count -= 1
        steps += deque(['R' * n, 'U' * n, 'U' * n])
        steps.rotate(-(c + 2))
        return ''.join(steps)

