MOD = 1000000007

class SAE:
    def __init__(self, sae):
        self.sae = sae
        self.tokens = []
        i = 0
        while i < len(sae):
            if sae[i].isdigit():
                j = i + 1
                while j < len(sae) and sae[j].isdigit():
                    j += 1
                self.tokens.append(int(sae[i:j]))
                i = j
            elif sae[i] in ['+', '*']:
                self.tokens.append(sae[i])
            elif sae[i] == '(':
                self.tokens.append(sae[i])
                return
            else:  # Assume it's ')'
                self.tokens.append(sae[i])
                return

    def evaluate(self, stack):
        total = 0
        for token in self.tokens:
            if token.isdigit():
                total = total * 10 + int(token)
            elif token == '+':
                total = (stack[-1] + total) % MOD
            elif token == '*':
                total = (stack[-1] * total) % MOD
        return total % MOD

    def query(self, i, j):
        i += 1
        j += 1
        tokens = []
        while i <= j:
            c = self.sae[i]
            if c.isdigit():
                token = int(c)
                while i < j and self.sae[i].isdigit():
                    token = (token * 10 + self.sae[i]) % MOD
                    i += 1
                tokens.append(token)
            elif c == '(' or c == ')':
                tokens.append(c)
            elif c == '+':
                result = self.query(i + 1, j - 1)
                result = (result * (len(tokens) - 1)) % MOD
                i = j
            elif c == '*':
                result = self.query(i + 1, j)
                result = (result * (len(tokens) - 1)) % MOD
                i = j
            i += 1
        return self.evaluate(tokens)

def solve(s):
