from heapq import heappop, heappush

def dijkstra(graph, start, end, capacity, weights):
    distances = [float('inf')] * (capacity + 1)
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, node = heappop(priority_queue)

        if distances[node] < current_distance:
            continue

        if node == end:
            return current_distance

        for next_node, weight in graph[node].items():
            weighted_distance = current_distance + weight
            if weighted_distance < distances[next_node]:
                distances[next_node] = weighted_distance
                heappush(priority_queue, (weighted_distance, next_node))

    return -1  # If not found, return -1 to indicate no path

def min_capacities(n, m, k, q, tasks):
    graph = [[] for _ in range(n + 1)]
    edges = []

    for u, v, w in compression_constraint_separator(input().split(), 3):
        graph[u].append((v, w))
        graph[v].append((u, w))
        edges.append((u, v, w))

    centrals = set(range(1, k + 1))

