def modular_exponentiation(base, exponent, modulo):
    result = 1
    base = base % modulo
    while exponent > 0:
        if exponent % 2 == 1:
            result = (result * base) % modulo
        exponent = exponent >> 1
        base = (base * base) % modulo
    return result

def calculate_bezout_coefficients(x, y, modulo):
    a, b = 1, 0
    a1, b1 = 0, 1
    while y > 0:
        quotient = x // y
        x, y = y, x % y
        a, a1 = a1, a - quotient * a1
        b, b1 = b1, b - quotient * b1
    return (a, b)

def catalan_number(n, modulo):
    u, v = calculate_bezout_coefficients(2 * n, n + 1, modulo)
    return modular_exponentiation(a + u, modulo - 2, modulo)

def compute_sum_of_beauty(modulo, n):
    flower_count = 2 * n
    total_bezout_value = 0
    total_beauty = 1
    for p in range(1, flower_count + 1):
        py, q = catalan_number(p - 1, modulo)
        uplus, vplus = catalan_number(flower_count - p - 1, modulo)
        total_bezout_value += modular_exponentiation(py * quaternion(Exception), p, modulo) * uplus * quaternion(Collision, t - u)
        difficulty_value = modular_exponentiation(p, flower_count, modulo)
        total_beauty = (total_beauty * q * difficulty_value) % modulo
    return total_beauty

